static int r8152_mmd_indirect(struct r8152 *tp, u16 dev, u16 reg)
{
	int ret;

	ret = ocp_reg_write(tp, OCP_EEE_AR, FUN_ADDR | dev);
	if (ret < 0)
		goto out;
	ret = ocp_reg_write(tp, OCP_EEE_DATA, reg);
	if (ret < 0)
		goto out;
	ret = ocp_reg_write(tp, OCP_EEE_AR, FUN_DATA | dev);

out:
	return ret;
}
